// The second synthetic replay clip (Black Water, ADR-0078, gap audit G12) is
// generated by scripts/fixtures/gen-synthetic-replay-002.sh and committed
// under testdata/synthetic/replay/black-water-001/. These tests are the
// generator's fence, the same way the first clip's determinism test fences
// gen-synthetic-replay.sh (internal/capture/replay):
//
//   - the committed clip is exactly what the committed generator writes
//     (byte-identical re-run), so a generator change is never silent;
//   - the rendered text lies inside the box's inner rect in every text
//     frame (the placement guard: a measurement bug that made long lines
//     overflow the box showed up here as bright pixels outside the rect —
//     OCR saw truncated words and the pipeline read a different line);
//   - the real Tesseract reads the Latin pages within tolerance of the
//     intended text, and reads the non-Latin page identically on every
//     frame of the page (stable placement; the eng model is not expected
//     to read it — the pipeline's expected behaviour is the abstain).

const secondClipDir = "black-water-001"

func runSecondClipGenerator(t *testing.T) string {
	t.Helper()
	for _, tool := range []string{"bash", "magick", "fc-match", "python3"} {
		if _, err := exec.LookPath(tool); err != nil {
			t.Skipf("NOT RUN: %s is required to regenerate the second replay clip", tool)
		}
	}
	script := filepath.Join("..", "..", "scripts", "fixtures", "gen-synthetic-replay-002.sh")
	out := t.TempDir()
	cmd := exec.Command("bash", script, out)
	if b, err := cmd.CombinedOutput(); err != nil {
		t.Fatalf("gen-synthetic-replay-002.sh: %v: %s", err, strings.TrimSpace(string(b)))
	}
	return out
}

// TestSecondReplayClipGeneratorDeterministic re-runs the generator into a
// temp dir and requires byte-identical output: the committed clip is the
// generator's output, never a hand-edited one (docs/spec/11 "Fixture
// origins", the first clip's same determinism discipline).
func TestSecondReplayClipGeneratorDeterministic(t *testing.T) {
	committed := filepath.Join("..", "..", "testdata", "synthetic", "replay", secondClipDir)
	if _, err := os.Stat(filepath.Join(committed, "truth.json")); err != nil {
		t.Skipf("NOT RUN: committed second clip missing (%v); run scripts/fixtures/gen-synthetic-replay-002.sh", err)
	}
	got := runSecondClipGenerator(t)
	files, err := filepath.Glob(filepath.Join(got, "*.png"))
	if err != nil || len(files) == 0 {
		t.Fatalf("generator wrote no frames: %v", err)
	}
	for _, f := range files {
		base := filepath.Base(f)
		a, err := os.ReadFile(f)
		if err != nil {
			t.Fatalf("read generated %s: %v", base, err)
		}
		b, err := os.ReadFile(filepath.Join(committed, base))
		if err != nil {
			t.Fatalf("committed clip missing %s (regenerate or the generator changed)", base)
		}
		if !bytes.Equal(a, b) {
			t.Errorf("frame %s is not byte-identical to the committed clip: the generator is not deterministic (or the committed clip drifted)", base)
		}
	}
	for _, name := range []string{"truth.json", "timestamps.json"} {
		a, err := os.ReadFile(filepath.Join(got, name))
		if err != nil {
			t.Fatalf("generator wrote no %s: %v", name, err)
		}
		b, err := os.ReadFile(filepath.Join(committed, name))
		if err != nil {
			t.Fatalf("committed clip missing %s: %v", name, err)
		}
		if !bytes.Equal(a, b) {
			t.Errorf("%s is not byte-identical to the committed clip", name)
		}
	}
}

// secondClipTruth is one truth.json row of the second clip: the fields the
// placement and OCR guards read (the rect is the inner box, the margin the
// text must stay inside).
type secondClipTruth struct {
	File string `json:"file"`
	Text string `json:"text"`
	Box  struct {
		X float64 `json:"x"`
		Y float64 `json:"y"`
		W float64 `json:"w"`
		H float64 `json:"h"`
	} `json:"box"`
	Rect struct {
		X float64 `json:"x"`
		Y float64 `json:"y"`
		W float64 `json:"w"`
		H float64 `json:"h"`
	} `json:"rect"`
	Size struct {
		W int `json:"w"`
		H int `json:"h"`
	} `json:"size"`
}

func loadSecondClipTruth(t *testing.T) []secondClipTruth {
	t.Helper()
	raw, err := os.ReadFile(filepath.Join("..", "..", "testdata", "synthetic", "replay", secondClipDir, "truth.json"))
	if err != nil {
		t.Fatalf("read second clip truth: %v", err)
	}
	var rows []secondClipTruth
	if err := json.Unmarshal(raw, &rows); err != nil {
		t.Fatalf("parse second clip truth: %v", err)
	}
	if len(rows) != 24 {
		t.Fatalf("second clip truth has %d rows, want 24", len(rows))
	}
	return rows
}

// TestSecondReplayClipTextInsideBox is the placement guard. In every text
// frame every bright (text-coloured) pixel of the box area must lie inside
// the truth rect — the box's inner area. The failure mode this pins: a
// width-measurement bug that lets a wrapped-or-single line overflow the box
// puts text pixels outside the rect, the OCR reads truncated words, and the
// matcher ranks a reading no human narrator would produce.
func TestSecondReplayClipTextInsideBox(t *testing.T) {
	rows := loadSecondClipTruth(t)
	clipDir := filepath.Join("..", "..", "testdata", "synthetic", "replay", secondClipDir)
	const textLuma = 210 // the text fill (#e8edf0 ≈ 236) is far above both the box fill, the border stroke (≈194) and the noisy scene (≤ ≈190)
	for _, row := range rows {
		if row.Text == "" {
			continue
		}
		img := openSecondClipFrame(t, clipDir, row.File)
		b := img.Bounds()
		sx, sy := row.Size.W, row.Size.H
		// The box area in pixels: only inside it can a placement bug put
		// text, and scanning the box (not the frame) keeps the scene's
		// gradient out of the comparison entirely.
		bx0, by0 := int(row.Box.X*float64(sx)), int(row.Box.Y*float64(sy))
		bx1, by1 := int((row.Box.X+row.Box.W)*float64(sx)), int((row.Box.Y+row.Box.H)*float64(sy))
		rx0, ry0 := int(row.Rect.X*float64(sx)), int(row.Rect.Y*float64(sy))
		rx1, ry1 := int((row.Rect.X+row.Rect.W)*float64(sx)), int((row.Rect.Y+row.Rect.H)*float64(sy))
		var outside int
		for y := by0; y < by1 && y < b.Max.Y; y++ {
			for x := bx0; x < bx1 && x < b.Max.X; x++ {
				r, g, bl, _ := img.At(x, y).RGBA()
				luma := (int(r) + int(g) + int(bl)) / (3 << 8)
				if luma < textLuma {
					continue
				}
				if x < rx0-2 || x > rx1+2 || y < ry0-2 || y > ry1+2 {
					outside++
				}
			}
		}
		if outside > 0 {
			t.Errorf("%s: %d bright text pixels outside the inner box rect: the rendered text overflows the box (the OCR would read truncated words)", row.File, outside)
		}
	}
}

// TestSecondReplayClipOCRStable runs the real Tesseract over the clip's pages
// through the pipeline's exact chain (region crop -> vision.DefaultSteps ->
// Tesseract psm 6, the same calls the pipeline makes; a raw 1x crop is a
// different instrument and misjudges the fixture): the Latin pages must be
// readable within tolerance of the intended line (the pipeline's commit
// depends on it), and the non-Latin page must produce an identical reading on
// every frame of the page — the eng model is not expected to read Cyrillic,
// but an unstable reading would mean an unstable rendering, which no
// assertion downstream could pin.
func TestSecondReplayClipOCRStable(t *testing.T) {
	if _, err := exec.LookPath("tesseract"); err != nil {
		t.Skip("NOT RUN: tesseract not installed")
	}
	rows := loadSecondClipTruth(t)
	clipDir := filepath.Join("..", "..", "testdata", "synthetic", "replay", secondClipDir)
	// The profile's region rect, the same values the pipeline hands to
	// vision.CropNormalized for this clip's profile.
	norm := vision.Rect{X: 0.085938, Y: 0.195833, W: 0.567188, H: 0.129167}
	read := func(row secondClipTruth) string {
		t.Helper()
		img := openSecondClipFrame(t, clipDir, row.File)
		crop := vision.CropNormalized(img, norm, vision.CropOptions{})
		res, err := ocr.Tesseract{Timeout: 60 * time.Second}.Recognize(context.Background(), vision.Preprocess(crop, vision.DefaultSteps()))
		if err != nil {
			t.Fatalf("tesseract on %s: %v", row.File, err)
		}
		return strings.Join(strings.Fields(res.Text), " ")
	}

	// Latin pages: one middle frame per page, within tolerance of the line.
	byLine := map[string][]secondClipTruth{}
	for _, r := range rows {
		if r.Text != "" {
			byLine[r.Text] = append(byLine[r.Text], r)
		}
	}
	for _, text := range []string{
		"You paid the ferryman. The crossing is done now.",
		"This is not a toll. This is a habit.",
	} {
		page := byLine[text]
		if len(page) == 0 {
			t.Fatalf("clip truth carries no frame for %q", text)
		}
		got := normOCR(read(page[len(page)/2]))
		want := normOCR(text)
		d := editDistance(got, want)
		if float64(d) > 0.15*float64(len(want)) {
			t.Errorf("%s (page %q): OCR %q is %d edits from the intended line (%d chars): the page is not OCR-stable", page[len(page)/2].File, text, got, d, len(want))
		}
	}
	// Non-Latin page: every frame of the page reads identically.
	cyrillic := "Вода помнит то, что люди прячут."
	page := byLine[cyrillic]
	if len(page) == 0 {
		t.Fatalf("clip truth carries no frame for the non-Latin page")
	}
	first := read(page[0])
	if first == "" {
		t.Fatalf("non-Latin page reads empty on %s: nothing for the matcher to abstain on (the scene or the text is missing)", page[0].File)
	}
	for _, r := range page[1:] {
		if got := read(r); got != first {
			t.Errorf("%s reads %q, %s read %q: the non-Latin page is not stable frame to frame", r.File, got, page[0].File, first)
		}
	}
	t.Logf("non-Latin page reading (eng model, expected garbage): %q", first)
}

func openSecondClipFrame(t *testing.T, clipDir, file string) image.Image {
	t.Helper()
	f, err := os.Open(filepath.Join(clipDir, file))
	if err != nil {
		t.Fatalf("open %s: %v", file, err)
	}
	defer f.Close()
	img, err := png.Decode(f)
	if err != nil {
		t.Fatalf("decode %s: %v", file, err)
	}
	return img
}

// normOCR reduces a reading to lowercase alphanumerics and single spaces,
// the way a tolerance comparison wants the noise out of both sides.
func normOCR(s string) string {
	var b strings.Builder
	prev := false
	for _, r := range strings.ToLower(s) {
		if (r >= 'a' && r <= 'z') || (r >= '0' && r <= '9') {
			b.WriteRune(r)
			prev = false
			continue
		}
		if !prev && b.Len() > 0 {
			b.WriteByte(' ')
			prev = true
		}
	}
	return b.String()
}

func editDistance(a, b string) int {
	ra, rb := []rune(a), []rune(b)
	prev := make([]int, len(rb)+1)
	for j := range prev {
		prev[j] = j
	}
	for i := 1; i <= len(ra); i++ {
		cur := make([]int, len(rb)+1)
		cur[0] = i
		for j := 1; j <= len(rb); j++ {
			cost := 1
			if ra[i-1] == rb[j-1] {
				cost = 0
			}
			cur[j] = min3(prev[j]+1, cur[j-1]+1, prev[j-1]+cost)
		}
		prev = cur
	}
	return prev[len(rb)]
}

func min3(a, b, c int) int {
	if a < b {
		if a < c {
			return a
		}
		return c
	}
	if b < c {
		return b
	}
	return c
}
